import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static int diff(int x, int y) {
        int z = x - y;
        if (z >= 0) {
            return z;
        }
        return z * (-1);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        Map<Character, Integer> m = new HashMap<>();
        Map<Character, Integer> mRev = new HashMap<>();
        char ch = 'a';
        for (int i = 1; i <= 26; i++) {
            m.put(ch, i);
            ch++;
        }
        char chRev = 'z';
        for (int i = 26; i >= 1; i--) {
            mRev.put(chRev, i);
            chRev--;
        }

        String s = scanner.next();
        int ans = 0;
        for (int i = 0; i < s.length(); i++) {
            int a, b;
            if (i == 0) {
                a = diff(m.get(s.charAt(i)), m.get('a'));
                b = diff(a, 26);
            } else {
                a = diff(m.get(s.charAt(i)), m.get(s.charAt(i - 1)));
                b = diff(a, 26);
            }
            if (a < b) {
                ans += a;
            } else {
                ans += b;
            }
        }

        System.out.println(ans);
        scanner.close();
    }
}

